import * as React from "react";
import { FunctionComponent, useMemo, type CSSProperties } from "react";
import * as styles from "./flight-card.module.css";

export type FlightCard2Type = {
  className?: string;
  airlineIcon?: string;
  airlineName?: string;
  departureTime?: string;
  travelTime?: string;
  arrivalTime?: string;
  price?: string;

  /** Style props */
  airlineIconOverflow?: CSSProperties["overflow"];
};

const FlightCard2: FunctionComponent<FlightCard2Type> = ({
  className = "",
  airlineIcon,
  airlineIconOverflow,
  airlineName,
  departureTime,
  travelTime,
  arrivalTime,
  price,
}) => {
  const airlineIconStyle: CSSProperties = useMemo(() => {
    return {
      overflow: airlineIconOverflow,
    };
  }, [airlineIconOverflow]);

  return (
    <div className={[styles.flightCard, className].join(" ")}>
      <div className={styles.airlineSection}>
        <img
          className={styles.airlineIcon}
          loading="lazy"
          alt=""
          src={airlineIcon}
          style={airlineIconStyle}
        />
        <div className={styles.airlineName}>{airlineName}</div>
      </div>
      <div className={styles.flightDetailsSection}>
        <div className={styles.departureDetails}>
          <div className={styles.departureTime}>{departureTime}</div>
          <div className={styles.departureAirport}>SIN</div>
        </div>
        <div className={styles.flightduration}>
          <img
            className={styles.flighticon}
            loading="lazy"
            alt=""
            src="/flighticon.svg"
          />
          <div className={styles.travelTime}>{travelTime}</div>
        </div>
        <div className={styles.arrivalDetails}>
          <div className={styles.departureTime}>{arrivalTime}</div>
          <div className={styles.departureAirport}>LAX</div>
        </div>
      </div>
      <div className={styles.priceSection}>
        <img className={styles.separatorIcon} alt="" src="/separator.svg" />
        <b className={styles.price}>{price}</b>
      </div>
    </div>
  );
};

export default FlightCard2;
