import * as React from "react";
import { FunctionComponent } from "react";
import * as styles from "./component11.module.css";

export type Component11Type = {
  className?: string;

  /** Variant props */
  states1?: string;
};

const Component11: FunctionComponent<Component11Type> = ({
  className = "",
  states1 = "default",
}) => {
  return (
    <input
      className={[styles.component1, className].join(" ")}
      type="checkbox"
      data-states={states1}
    />
  );
};

export default Component11;
